<template><Card><h2>履约核查</h2><p>按店铺核查四种履约方式、固定费用与点位状态。</p><StatusPanel :error="error" :loading="loading"/><div class="s1-toolbar"><Input v-model="targetStore" placeholder="店铺编号" style="width:250px"/><Select v-model="type" clearable placeholder="全部点位类型" style="width:200px"><Option value="COMMUNITY_PICKUP">社区自提</Option><Option value="STORE_REDEMPTION">到店核销</Option></Select><Button type="primary" @click="page=1;reload()">核查</Button></div><RecordDetail v-if="selected" :value="{configuration:selected}"/><Table :data="records" :columns="columns" :loading="loading" no-data-text="暂无点位"><template slot="type" slot-scope="{row}">{{label(row.type)}}</template><template slot="enabled" slot-scope="{row}">{{row.enabled?'启用':'停用'}}</template><template slot="detail" slot-scope="{row}"><Button size="small" @click="point=row;show=true">查看</Button></template></Table><Page :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/><Drawer v-model="show" title="点位核查" width="80"><RecordDetail v-if="point" :value="point"/></Drawer></Card></template>
<script>import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import StatusPanel from './StatusPanel';import RecordDetail from './RecordDetail';export default {mixins:[pageMixin],components:{StatusPanel,RecordDetail},data:()=>({targetStore:'',type:'',point:null,show:false,columns:[{title:'点位',key:'name'},{title:'类型',slot:'type'},{title:'状态',slot:'enabled',width:100},{title:'地址',key:'address',minWidth:220},{title:'版本',key:'version',width:90},{title:'操作',slot:'detail',width:100}]}),methods:{async reload(){if(!this.targetStore){this.error='请填写店铺编号。';return;}try{this.selected=await s1Read('/stores/'+this.targetStore+'/fulfillment');await this.load('/stores/'+this.targetStore+'/points',{type:this.type||undefined});}catch(e){this.error=e.message;}}}};</script><style scoped>.s1-toolbar{display:flex;gap:12px;margin:18px 0}</style>
